import{_ as a,o as s,c as t,a2 as o}from"./chunks/framework.BS0bAV7E.js";const u=JSON.parse('{"title":"Boot modes: BIOS, UEFI, and the A/B slot menu","description":"","frontmatter":{},"headers":[],"relativePath":"manual/boot-modes.md","filePath":"manual/boot-modes.md"}'),n={name:"manual/boot-modes.md"};function i(l,e,r,d,c,h){return s(),t("div",null,[...e[0]||(e[0]=[o(`<h1 id="boot-modes-bios-uefi-and-the-a-b-slot-menu" tabindex="-1">Boot modes: BIOS, UEFI, and the A/B slot menu <a class="header-anchor" href="#boot-modes-bios-uefi-and-the-a-b-slot-menu" aria-label="Permalink to &quot;Boot modes: BIOS, UEFI, and the A/B slot menu&quot;">​</a></h1><h2 id="the-iso-is-hybrid" tabindex="-1">The ISO is hybrid <a class="header-anchor" href="#the-iso-is-hybrid" aria-label="Permalink to &quot;The ISO is hybrid&quot;">​</a></h2><p><code>build/opencube.iso</code> (the release asset) carries two boot paths:</p><ul><li><strong>Legacy BIOS</strong>: an El Torito boot image (GRUB i386-pc, built by <code>tools/build_iso.sh</code> with <code>grub-mkimage</code> + <code>xorriso</code>).</li><li><strong>UEFI</strong>: an EFI boot image (<code>x86_64-efi</code>) on the same ISO.</li></ul><p>Both paths load the same kernel ELF and attach the kernel itself as a multiboot2 module tagged <code>self</code> - this is the mainstream installer pattern: the <code>install</code> and <code>abdisk</code> commands copy <em>the exact kernel that is currently running</em> onto a target disk, so an installed system always matches its installer.</p><h2 id="the-grub-menu" tabindex="-1">The GRUB menu <a class="header-anchor" href="#the-grub-menu" aria-label="Permalink to &quot;The GRUB menu&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>* Open Cube OS (slot ISO)</span></span>
<span class="line"><span>  Open Cube OS (slot A, force)</span></span>
<span class="line"><span>  Open Cube OS (slot B, force)</span></span></code></pre></div><ul><li><strong>slot ISO</strong> - the default. Boot the kernel from the boot medium and read the A/B boot flag to decide which disk slot to chain (falls back to the ISO kernel when no flag exists).</li><li><strong>slot A / slot B force</strong> - ignore the flag and boot that disk slot directly. This is the recovery path when a bad update leaves the active slot unbootable: pick the other slot from the menu.</li></ul><p>The menu auto-boots the highlighted entry after 5 seconds.</p><h2 id="what-the-kernel-does-after-grub" tabindex="-1">What the kernel does after GRUB <a class="header-anchor" href="#what-the-kernel-does-after-grub" aria-label="Permalink to &quot;What the kernel does after GRUB&quot;">​</a></h2><p>Boot order (this is exactly the serial log):</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>multiboot2 handshake OK</span></span>
<span class="line"><span>long mode entry OK</span></span>
<span class="line"><span>framebuffer 800x600x32 OK</span></span>
<span class="line"><span>console grid / 8x16 font engine OK</span></span>
<span class="line"><span>IDT + GDT + TSS (256 gates) OK</span></span>
<span class="line"><span>8259 PIC remap (IRQ0-15 -&gt; vec 32-47) OK</span></span>
<span class="line"><span>PIT @ 100 Hz + tick counter OK</span></span>
<span class="line"><span>PS/2 keyboard OK</span></span>
<span class="line"><span>COM1 serial RX OK</span></span>
<span class="line"><span>console input line editor OK</span></span>
<span class="line"><span>interrupts enabled (sti) OK</span></span>
<span class="line"><span>exception self-test: 3/3 (#DE/#UD/#PF) OK</span></span>
<span class="line"><span>PMM / VMM / heap OK</span></span>
<span class="line"><span>... drivers, VFS, network ...</span></span>
<span class="line"><span>shell command system (233 commands) OK</span></span>
<span class="line"><span>boot complete OK</span></span>
<span class="line"><span>crash recovery armed (panic + dump + crashlog) OK</span></span></code></pre></div><p>The multiboot2 parser (<code>kernel/arch/x86_64/arch_multiboot2.c</code>) reads the framebuffer tag, the memory map, the command line and the ACPI RSDP tags (types 14/15) that GRUB forwards from firmware - on UEFI boots the RSDP comes through this path, on BIOS boots the ACPI driver can also scan memory.</p><h2 id="boot-arguments" tabindex="-1">Boot arguments <a class="header-anchor" href="#boot-arguments" aria-label="Permalink to &quot;Boot arguments&quot;">​</a></h2><p>GRUB passes the kernel command line; <code>grub.cfg</code> uses it to pass <code>BOOT_SLOT=ISO|A|B</code> plus console preferences. Inside a running system, <code>uname -a</code> shows the version and build, and <code>abcfg</code> prints the exact grub.cfg files that <code>abdisk</code>/<code>install</code> generate.</p><h2 id="persistence-the-etc-volume" tabindex="-1">Persistence: the /etc volume <a class="header-anchor" href="#persistence-the-etc-volume" aria-label="Permalink to &quot;Persistence: the /etc volume&quot;">​</a></h2><p>The system looks for a FAT32 volume to mount at <code>/etc</code>. When you boot the plain ISO there is none - configuration is ephemeral. <code>install</code> creates one on the target disk (it holds <code>opencube.conf</code>, SSH host keys, <code>kernel.log*</code>, crash dumps). If you only want persistence without installing, create the volume by hand:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>oc&gt; abdisk &lt;dev&gt;       (A/B disk with /etc volume - destroys data!)</span></span></code></pre></div><h2 id="booting-real-hardware" tabindex="-1">Booting real hardware <a class="header-anchor" href="#booting-real-hardware" aria-label="Permalink to &quot;Booting real hardware&quot;">​</a></h2><p>Write the ISO to a USB stick (<code>dd if=opencube.iso of=/dev/sdX</code> or your favourite tool). The requirements are modest: x86_64 CPU, 512 MiB RAM. Boot through BIOS or UEFI firmware as you prefer - both images are on the stick.</p>`,20)])])}const m=a(n,[["render",i]]);export{u as __pageData,m as default};
